1	package clinical
2	
3	import (
4		"fmt"
5		"strings"
6		"unicode/utf8"
7	)
8	
9	// validContent 校验诊断/医嘱正文：非空白且必须是完整合法的 UTF-8。
10	// 本地快照以 JSON 落盘，encoding/json 会把无效 UTF-8 字节静默替换为
11	// U+FFFD——若放行，当次查询看到的是原字节而重开后正文已被改写。因此
12	// 夹带不完整多字节字符、孤立续字节等任何无效序列的正文一律拒绝，
13	// 绝不靠替换、截断或跳过坏字节继续保存。用户明确输入的合法 U+FFFD
14	// 字符本身是合法 UTF-8，不受此限制。
15	func validContent(content string) bool {
16		return utf8.ValidString(content)
17	}
18	
19	// CreateDraft 在某次就诊下新建一条诊断或医嘱草稿。
20	// 患者必须存在且未停用；就诊必须属于该患者（否则 ErrMismatchedPatient）；
21	// 类别必须是 Diagnosis 或 Order，内容不能为空。
22	func (s *Store) CreateDraft(actor Actor, patientID, encounterID ID, category, content string) (Record, error) {
23		if !actor.valid() || !actor.IsInternal() {
24			return Record{}, ErrAccessDenied
25		}
26		if patientID == "" || encounterID == "" {
27			return Record{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
28		}
29		if !validCategory(category) {
30			return Record{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
31		}
32		if strings.TrimSpace(content) == "" {
33			return Record{}, fmt.Errorf("%w: draft content is required", ErrInvalidArgument)
34		}
35		if !validContent(content) {
36			return Record{}, fmt.Errorf("%w: draft content must be valid UTF-8", ErrInvalidArgument)
37		}
38	
39		var result Record
40		err := s.mutate(func(snap *snapshot) error {
41			if _, err := requireActivePatient(snap, patientID); err != nil {
42				return err
43			}
44			if _, err := requireEncounter(snap, patientID, encounterID); err != nil {
45				return err
46			}
47			r := &Record{
48				ID:           newID("rec"),
49				PatientID:    patientID,
50				EncounterID:  encounterID,
51				Category:     category,
52				DraftContent: content,
53				HasDraft:     true,
54			}
55			snap.Records[r.ID] = r
56			result = *r
57			return nil
58		})
59		return result, err
60	}
61	
62	// UpdateDraft 修改尚未生效的草稿内容。已生效的记录不能再走草稿路径
63	// （返回 ErrActive），必须使用 CorrectRecord 更正。
64	func (s *Store) UpdateDraft(actor Actor, recordID ID, content string) (Record, error) {
65		if !actor.valid() || !actor.IsInternal() {
66			return Record{}, ErrAccessDenied
67		}
68		if strings.TrimSpace(content) == "" {
69			return Record{}, fmt.Errorf("%w: draft content is required", ErrInvalidArgument)
70		}
71		if !validContent(content) {
72			return Record{}, fmt.Errorf("%w: draft content must be valid UTF-8", ErrInvalidArgument)
73		}
74	
75		var result Record
76		err := s.mutate(func(snap *snapshot) error {
77			r, err := requireDraftRecord(snap, recordID)
78			if err != nil {
79				return err
80			}
81			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
82				return err
83			}
84			r.DraftContent = content
85			result = *r
86			return nil
87		})
88		return result, err
89	}
90	
91	// DeleteDraft 删除一条尚未生效的草稿及其记录。草稿从未生效，
92	// 因此删除不影响任何生效内容，也不产生审计事件。
93	func (s *Store) DeleteDraft(actor Actor, recordID ID) error {
94		if !actor.valid() || !actor.IsInternal() {
95			return ErrAccessDenied
96		}
97		return s.mutate(func(snap *snapshot) error {
98			r, err := requireDraftRecord(snap, recordID)
99			if err != nil {
100				return err
101			}
102			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
103				return err
104			}
105			delete(snap.Records, r.ID)
106			return nil
107		})
108	}
109	
110	// ActivateRecord 使草稿生效：固化当时的完整内容与时间为第 1 版。
111	// 生效后草稿被清除，记录不能再被直接覆盖或删除，只能更正。
112	// 生效与审计事件在同一次原子落盘中保留。
113	func (s *Store) ActivateRecord(actor Actor, recordID ID) (Version, error) {
114		if !actor.valid() || !actor.IsInternal() {
115			return Version{}, ErrAccessDenied
116		}
117		var result Version
118		err := s.mutate(func(snap *snapshot) error {
119			r, err := requireDraftRecord(snap, recordID)
120			if err != nil {
121				return err
122			}
123			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
124				return err
125			}
126			now := s.now()
127			v := &Version{
128				ID:        newID("ver"),
129				RecordID:  r.ID,
130				Number:    1,
131				Content:   r.DraftContent,
132				Category:  r.Category,
133				CreatedAt: now,
134			}
135			snap.Versions[v.ID] = v
136			r.CurrentVersionID = v.ID
137			r.Versions = append(r.Versions, v.ID)
138			r.HasDraft = false
139			r.DraftContent = ""
140			s.addAudit(snap, r.PatientID, actor, ActionActivated, "record", r.ID, now)
141			result = *v
142			return nil
143		})
144		return result, err
145	}
146	
147	// CorrectRecord 对当前生效版本进行更正，生成同一条记录的新版本。
148	//
149	// reason 必须非空；expectedCurrentVersion 必须等于记录当前版本号，
150	// 否则返回 ErrConflict 且状态保持不变。旧版本内容、版本关系（PrevID）
151	// 与更正原因都会保留。新版本与审计事件一同原子落盘。
152	func (s *Store) CorrectRecord(actor Actor, recordID ID, expectedCurrentVersion int, content, reason string) (Version, error) {
153		if !actor.valid() || !actor.IsInternal() {
154			return Version{}, ErrAccessDenied
155		}
156		if strings.TrimSpace(content) == "" {
157			return Version{}, fmt.Errorf("%w: corrected content is required", ErrInvalidArgument)
158		}
159		if !validContent(content) {
160			return Version{}, fmt.Errorf("%w: corrected content must be valid UTF-8", ErrInvalidArgument)
161		}
162		if strings.TrimSpace(reason) == "" {
163			return Version{}, fmt.Errorf("%w: correction reason is required", ErrInvalidArgument)
164		}
165		if expectedCurrentVersion <= 0 {
166			return Version{}, fmt.Errorf("%w: expected current version must be positive", ErrInvalidArgument)
167		}
168	
169		var result Version
170		err := s.mutate(func(snap *snapshot) error {
171			r := snap.Records[recordID]
172			if r == nil {
173				return fmt.Errorf("%w: record %q", ErrNotFound, recordID)
174			}
175			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
176				return err
177			}
178			if r.CurrentVersionID == "" {
179				return fmt.Errorf("%w: record %q has no effective version; activate its draft first", ErrInvalidArgument, recordID)
180			}
181			current := snap.Versions[r.CurrentVersionID]
182			if current == nil {
183				// 内部状态不应出现；按不存在处理，拒绝写入。
184				return fmt.Errorf("%w: current version %q", ErrNotFound, r.CurrentVersionID)
185			}
186			if current.Number != expectedCurrentVersion {
187				return fmt.Errorf("%w: record %q is at version %d, not %d",
188					ErrConflict, recordID, current.Number, expectedCurrentVersion)
189			}
190	
191			now := s.now()
192			v := &Version{
193				ID:        newID("ver"),
194				RecordID:  r.ID,
195				Number:    current.Number + 1,
196				Content:   content,
197				Category:  r.Category,
198				CreatedAt: now,
199				PrevID:    current.ID,
200				Reason:    reason,
201			}
202			snap.Versions[v.ID] = v
203			r.CurrentVersionID = v.ID
204			r.Versions = append(r.Versions, v.ID)
205			s.addAudit(snap, r.PatientID, actor, ActionCorrected, "record", r.ID, now)
206			result = *v
207			return nil
208		})
209		return result, err
210	}
211	
212	// requireDraftRecord 取出仍处于草稿阶段（有草稿且尚无生效版本）的记录。
213	func requireDraftRecord(snap *snapshot, recordID ID) (*Record, error) {
214		r := snap.Records[recordID]
215		if r == nil {
216			return nil, fmt.Errorf("%w: record %q", ErrNotFound, recordID)
217		}
218		if r.CurrentVersionID != "" || !r.HasDraft {
219			return nil, fmt.Errorf("%w: record %q is already effective", ErrActive, recordID)
220		}
221		return r, nil
222	}
