1	package clinical
2	
3	import (
4		"sort"
5	)
6	
7	// RecordHistory 是内部使用者看到的一条记录的完整视图：
8	// 草稿（若有）与全部历史版本（旧到新，含更正原因）。
9	type RecordHistory struct {
10		Record         Record
11		DraftContent   string
12		HasDraft       bool
13		CurrentVersion *Version
14		Versions       []Version // 旧到新
15	}
16	
17	// PatientChart 是内部使用者按患者看到的完整档案。
18	type PatientChart struct {
19		Patient     Patient
20		Encounters  []Encounter
21		Records     []RecordHistory
22		AuditEvents []AuditEvent
23	}
24	
25	// Chart 返回患者的完整档案，包含所有草稿、全部版本（含旧内容、版本关系
26	// 与更正原因）以及审计事件。仅供内部使用者；患者停用后仍可查看。
27	func (s *Store) Chart(actor Actor, patientID ID) (PatientChart, error) {
28		if !actor.valid() || !actor.IsInternal() {
29			return PatientChart{}, ErrAccessDenied
30		}
31		var chart PatientChart
32		err := s.view(func(snap *snapshot) error {
33			p, err := requirePatient(snap, patientID)
34			if err != nil {
35				return err
36			}
37			chart.Patient = *p
38	
39			for _, e := range snap.Encounters {
40				if e.PatientID == patientID {
41					chart.Encounters = append(chart.Encounters, *e)
42				}
43			}
44			sortEncounters(chart.Encounters)
45	
46			var recs []*Record
47			for _, r := range snap.Records {
48				if r.PatientID == patientID {
49					recs = append(recs, r)
50				}
51			}
52			sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })
53	
54			for _, r := range recs {
55				chart.Records = append(chart.Records, buildHistory(snap, r))
56			}
57	
58			for _, ev := range snap.AuditEvents {
59				if ev.PatientID == patientID {
60					// 审计事件按追加顺序保存，即真实发生顺序；
61					// 时间戳相同（如注入时钟）时也不能打乱。
62					chart.AuditEvents = append(chart.AuditEvents, *ev)
63				}
64			}
65			return nil
66		})
67		return chart, err
68	}
69	
70	// AuditEvents 仅供内部使用者按患者查看审计事件，按发生时间旧到新。
71	func (s *Store) AuditEvents(actor Actor, patientID ID) ([]AuditEvent, error) {
72		chart, err := s.Chart(actor, patientID)
73		if err != nil {
74			return nil, err
75		}
76		return chart.AuditEvents, nil
77	}
78	
79	// EncounterRecords 仅供内部使用者查看某次就诊下的记录及完整历史。
80	func (s *Store) EncounterRecords(actor Actor, patientID, encounterID ID) ([]RecordHistory, error) {
81		if !actor.valid() || !actor.IsInternal() {
82			return nil, ErrAccessDenied
83		}
84		var out []RecordHistory
85		err := s.view(func(snap *snapshot) error {
86			if _, err := requirePatient(snap, patientID); err != nil {
87				return err
88			}
89			if _, err := requireEncounter(snap, patientID, encounterID); err != nil {
90				return err
91			}
92			var recs []*Record
93			for _, r := range snap.Records {
94				if r.EncounterID == encounterID {
95					recs = append(recs, r)
96				}
97			}
98			sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })
99			for _, r := range recs {
100				out = append(out, buildHistory(snap, r))
101			}
102			return nil
103		})
104		return out, err
105	}
106	
107	func buildHistory(snap *snapshot, r *Record) RecordHistory {
108		// 返回的记录必须是独立副本：Versions 切片与存储中的记录共享底层数组时，
109		// 调用方改动查询结果会写回正式历史。这里深拷贝，保证修改手中的结果
110		// 只影响该结果本身。
111		rec := *r
112		rec.Versions = append([]ID(nil), r.Versions...)
113		rh := RecordHistory{
114			Record:       rec,
115			DraftContent: r.DraftContent,
116			HasDraft:     r.HasDraft,
117		}
118		for _, vid := range r.Versions {
119			if v := snap.Versions[vid]; v != nil {
120				rh.Versions = append(rh.Versions, *v)
121			}
122		}
123		sort.Slice(rh.Versions, func(i, j int) bool { return rh.Versions[i].Number < rh.Versions[j].Number })
124		if r.CurrentVersionID != "" {
125			if v := snap.Versions[r.CurrentVersionID]; v != nil {
