133	// currentEffective 取出记录当前生效版本的对外内容；无生效版本时第二返回值为 false。
134	func currentEffective(snap *snapshot, r *Record) (EffectiveRecord, bool) {
135		if r.CurrentVersionID == "" {
136			return EffectiveRecord{}, false
137		}
138		v := snap.Versions[r.CurrentVersionID]
