291	// ---- 隔离：在手中的结果上整理内容，改不到正式病历，也改不到另一份结果 ----
292	
293	func TestEncounterRecordsResultIsDetachedFromStore(t *testing.T) {
294		s, _ := newTestStore(t)
295		pid, e1 := setupPatientEncounter(t, s)
296		e2, err := s.AddEncounter(doc, pid, time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))
297		if err != nil {
298			t.Fatal(err)
299		}
300	
301		draftDx := mustCreateDraft(t, s, pid, e1, Diagnosis, "草稿诊断内容")
302		corrOrd := mustCreateDraft(t, s, pid, e1, Order, "医嘱第 1 版内容")
303		ov1 := mustActivate(t, s, corrOrd)
304		ov2 := mustCorrect(t, s, corrOrd, 1, "医嘱第 2 版内容", "医嘱更正原因")
305		// 另一就诊放一条记录，确认版本不会跨记录串台。
306		other := mustCreateDraft(t, s, pid, e2.ID, Order, "另一就诊的医嘱")
307		mustActivate(t, s, other)
308	
309		// 第一份结果作为基线；随后取得第二份独立结果。
310		first, err := s.EncounterRecords(doc, pid, e1)
311		if err != nil {
312			t.Fatal(err)
313		}
314		want := snapshotHistories(first)
315		auditBefore := mustAudit(t, s, pid)
316	
317		second, err := s.EncounterRecords(doc, pid, e1)
318		if err != nil {
319			t.Fatal(err)
320		}
321	
322		// 在第一份结果上做广泛的本地修改（草稿与已更正记录都改）。
323		for i := range first {
324			tamperHistory(&first[i])
325		}
326	
327		// 先前取得的另一份结果保持原值：不丢版本、不换顺序、不混入其他记录的版本。
328		assertHistoriesMatches(t, second, want, "previously fetched result after tampering")
329		for _, h := range second {
330			for _, v := range h.Versions {
331				if v.ID == "" || v.RecordID != h.Record.ID {
332					t.Fatalf("version %+v does not belong to its record", v)
333				}
334			}
335		}
336	
337		// 随后重新读取的正式历史同样保持原值。
338		again, err := s.EncounterRecords(doc, pid, e1)
339		if err != nil {
340			t.Fatal(err)
341		}
342		assertHistoriesMatches(t, again, want, "official history re-read after tampering")
343	
344		// 完整档案视图里该就诊的部分也不得被波及。
345		chart, err := s.Chart(doc, pid)
346		if err != nil {
347			t.Fatal(err)
348		}
349		var chartE1 []RecordHistory
350		for _, h := range chart.Records {
351			if h.Record.EncounterID == e1 {
352				chartE1 = append(chartE1, h)
353			}
354		}
355		assertHistoriesMatches(t, chartE1, want, "chart view after tampering")
356	
357		// 本地整理既不是查询也不是写操作：不能增加、更换或删除正式审计事件。
358		auditAfter := mustAudit(t, s, pid)
359		if len(auditAfter) != len(auditBefore) {
360			t.Fatalf("local mutation changed audit events: before=%d after=%d", len(auditBefore), len(auditAfter))
361		}
362		for i := range auditBefore {
363			if auditBefore[i] != auditAfter[i] {
364				t.Fatalf("audit event %d changed:\n before=%+v\n after=%+v", i, auditBefore[i], auditAfter[i])
365			}
366		}
367	
368		// 防止 unused（这些标识同时是上面版本链断言的对象来源）。
369		_ = draftDx
370		_ = ov1
371		_ = ov2
372	}
