package clinical

import (
	"fmt"
	"time"
)

// RegisterPatient 登记一名合成患者并返回其稳定标识。
// 只有内部使用者可以登记患者。
func (s *Store) RegisterPatient(actor Actor, name string) (Patient, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Patient{}, ErrAccessDenied
	}
	if name == "" {
		return Patient{}, fmt.Errorf("%w: patient name is required", ErrInvalidArgument)
	}

	var result Patient
	err := s.mutate(func(snap *snapshot) error {
		now := s.now()
		p := &Patient{
			ID:        newID("pat"),
			Name:      name,
			Source:    SyntheticSource,
			CreatedAt: now,
		}
		snap.Patients[p.ID] = p
		result = *p
		return nil
	})
	return result, err
}

// AddEncounter 在患者档案下登记一次就诊。患者必须存在且未停用。
// occurredAt 为零值时取当前时间。
func (s *Store) AddEncounter(actor Actor, patientID ID, occurredAt time.Time) (Encounter, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Encounter{}, ErrAccessDenied
	}
	if patientID == "" {
		return Encounter{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
	}

	var result Encounter
	err := s.mutate(func(snap *snapshot) error {
		p, err := requireActivePatient(snap, patientID)
		if err != nil {
			return err
		}
		at := occurredAt
		if at.IsZero() {
			at = s.now()
		}
		e := &Encounter{
			ID:         newID("enc"),
			PatientID:  p.ID,
			OccurredAt: at.UTC(),
			CreatedAt:  s.now(),
		}
		snap.Encounters[e.ID] = e
		result = *e
		return nil
	})
	return result, err
}

// DeactivatePatient 停用患者档案。停用后不能新增就诊、改动草稿、使记录生效、
// 进行更正或新建授权，接收方也无法继续读取；内部使用者仍可查看全部历史。
//
// 重复停用返回成功且不产生额外变化（不新增审计事件）。
func (s *Store) DeactivatePatient(actor Actor, patientID ID) error {
	if !actor.valid() || !actor.IsInternal() {
		return ErrAccessDenied
	}
	return s.mutate(func(snap *snapshot) error {
		p, err := requirePatient(snap, patientID)
		if err != nil {
			return err
		}
		if p.Deactivated {
			// 幂等：正式保存的患者状态已经是停用。确认已有结果即可——保持首次
			// 停用的时间与操作身份，不生成额外变化或事件，也不落盘：重复确认不
			// 依赖当前能否写入本地数据，任何内部使用者的合法确认都得到同一结果，
			// 且不能把首次停用改成确认者的信息。一次保存失败的停用尝试不会改变
			// 正式状态，因此不会被当作成功依据。
			return errUnchanged
		}
		now := s.now()
		p.Deactivated = true
		s.addAudit(snap, p.ID, actor, ActionDeactivated, "patient", p.ID, now)
		return nil
	})
}

// GetPatient 返回患者档案。仅供内部使用者。
func (s *Store) GetPatient(actor Actor, patientID ID) (Patient, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Patient{}, ErrAccessDenied
	}
	var result Patient
	err := s.view(func(snap *snapshot) error {
		p, err := requirePatient(snap, patientID)
		if err != nil {
			return err
		}
		result = *p
		return nil
	})
	return result, err
}

// ListEncounters 按发生时间顺序返回患者的全部就诊。仅供内部使用者。
func (s *Store) ListEncounters(actor Actor, patientID ID) ([]Encounter, error) {
	if !actor.valid() || !actor.IsInternal() {
		return nil, ErrAccessDenied
	}
	var result []Encounter
	err := s.view(func(snap *snapshot) error {
		if _, err := requirePatient(snap, patientID); err != nil {
			return err
		}
		for _, e := range snap.Encounters {
			if e.PatientID == patientID {
				result = append(result, *e)
			}
		}
		sortEncounters(result)
		return nil
	})
	return result, err
}

func requirePatient(snap *snapshot, patientID ID) (*Patient, error) {
	p := snap.Patients[patientID]
	if p == nil {
		return nil, fmt.Errorf("%w: patient %q", ErrNotFound, patientID)
	}
	return p, nil
}

func requireActivePatient(snap *snapshot, patientID ID) (*Patient, error) {
	p, err := requirePatient(snap, patientID)
	if err != nil {
		return nil, err
	}
	if p.Deactivated {
		return nil, fmt.Errorf("%w: patient %q", ErrDeactivated, patientID)
	}
	return p, nil
}

// requireEncounter 校验就诊存在且属于给定患者。
// 引用不存在的就诊返回 ErrNotFound；就诊属于其他患者返回 ErrMismatchedPatient。
func requireEncounter(snap *snapshot, patientID, encounterID ID) (*Encounter, error) {
	e := snap.Encounters[encounterID]
	if e == nil {
		return nil, fmt.Errorf("%w: encounter %q", ErrNotFound, encounterID)
	}
	if patientID != "" && e.PatientID != patientID {
		return nil, fmt.Errorf("%w: encounter %q belongs to patient %q, not %q",
			ErrMismatchedPatient, encounterID, e.PatientID, patientID)
	}
	return e, nil
}

func validCategory(c string) bool { return c == Diagnosis || c == Order }

// 命令 list_authorizations 演示内部使用者如何用 ListAuthorizations 查看某名
// 合成患者已保存的授权清单。
//
// 清单是“历史视图”，不是“接收方此刻能读什么”：同一名患者授予两个接收方的
// 当前有效、尚未开始、已经到期与已经撤回的授权都会原样列出，每条保留各自的
// 整类范围、限定记录范围、时间窗与撤回时间。示例同时演示：
//   - 只按患者查询（接收方参数传空字符串）与再指定接收方的差异；
//   - 另一名患者授权给同一个接收方不会混入本患者清单；
//   - 患者存在但没有授权、指定接收方未获该患者授权，都是成功返回空清单；
//   - 清单里有授权不代表接收方此刻能读取（未开始的授权仍读取被拒）；
//   - 两种失败：内部使用者查询不存在的患者得到 ErrNotFound；接收方即使持有
//     有效授权也不能调用这个内部查询，得到 ErrAccessDenied 且无授权资料；
//   - 患者停用后内部使用者仍能列出历史授权，接收方读取则被拒绝。
//
// 全程只使用合成患者资料。运行：
//
//	go run ./examples/list_authorizations
package main

import (
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/bengzyyys/clinical-exchange/clinical"
)

func main() {
	dir, err := os.MkdirTemp("", "clinical-list-auth-")
	must("创建临时数据目录", err)
	defer os.RemoveAll(dir)

	store, err := clinical.Open(dir)
	must("打开本地存储", err)
	defer store.Close()

	doctor := clinical.InternalActor("doctor-1")
	insurer1 := clinical.ReceiverActor("insurer-1")
	insurer2 := clinical.ReceiverActor("insurer-2")
	insurer3 := clinical.ReceiverActor("insurer-3")

	now := time.Now()

	// ---- 准备合成患者、一次就诊与已生效记录 ----
	patient, err := store.RegisterPatient(doctor, "合成患者戊")
	must("登记合成患者戊", err)
	encounter, err := store.AddEncounter(doctor, patient.ID, now)
	must("登记就诊", err)

	diag1, err := store.CreateDraft(doctor, patient.ID, encounter.ID,
		clinical.Diagnosis, "合成诊断一：高血压 I10")
	must("创建第一条诊断草稿", err)
	_, err = store.ActivateRecord(doctor, diag1.ID)
	must("生效第一条诊断", err)

	diag2, err := store.CreateDraft(doctor, patient.ID, encounter.ID,
		clinical.Diagnosis, "合成诊断二：2 型糖尿病 E11")

